<?php
namespace App\Console\Commands;
use App\Models\AcumaticaSalesOrder;
use App\Models\FulfillmentHistorySnapshot;
use Illuminate\Console\Command;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;
use Throwable;
class BackfillFulfillmentHistory extends Command {
 protected $signature='orderwatch:backfill-fulfillment-history {--connection=historical} {--from=2026-06-01} {--to=2026-06-30} {--dry-run}';
 protected $description='Import immutable first-completed fulfillment snapshots from an isolated historical database';
 public function handle():int{$connection=(string)$this->option('connection');$from=(string)$this->option('from');$to=(string)$this->option('to');$dry=(bool)$this->option('dry-run');if($connection===config('database.default')){$this->error('Historical connection must not be the active database connection.');return self::FAILURE;}try{DB::connection($connection)->getPdo();}catch(Throwable $e){$this->error('Historical read-only connection unavailable: '.$e->getMessage());return self::FAILURE;}$schema=Schema::connection($connection);if(!$schema->hasTable('acumatica_sales_orders')||!$schema->hasTable('acumatica_sales_order_lines')){$this->error('Historical database lacks required sales order tables.');return self::FAILURE;}$orders=DB::connection($connection)->table('acumatica_sales_orders')->whereRaw('LOWER(TRIM(status)) = ?',['completed'])->whereBetween('order_date',[$from.' 00:00:00',$to.' 23:59:59'])->orderBy('completed_at')->orderBy('synced_at')->get();$recovered=0;$missing=0;$rejected=0;$value=0.0;foreach($orders as $source){$lines=DB::connection($connection)->table('acumatica_sales_order_lines')->where('sales_order_id',$source->id)->get();$local=AcumaticaSalesOrder::where('acumatica_order_nbr',$source->acumatica_order_nbr)->first();if($lines->isEmpty()||!$local){$missing++;continue;}if(FulfillmentHistorySnapshot::where('order_nbr',$source->acumatica_order_nbr)->exists())continue;$lineRows=[];$tot=['ordered'=>0.0,'delivered'=>0.0,'missing'=>0.0,'value'=>0.0];foreach($lines as $line){$ordered=(float)$line->order_qty;$delivered=(float)($line->qty_on_shipments?:$line->shipped_qty);$cancelled=(float)($line->cancelled_qty??0);$open=max((float)($line->open_qty??max($ordered-$delivered-$cancelled,0)),0);$price=(float)$line->unit_price;if($price<=0&&$open>0)$rejected++;$short=round($open*$price,2);$lineRows[]=['line_nbr'=>(int)$line->line_nbr,'inventory_id'=>(string)$line->inventory_id,'description'=>$line->description,'order_qty'=>$ordered,'delivered_qty'=>$delivered,'cancelled_qty'=>$cancelled,'open_qty'=>$open,'open_qty_explicit'=>true,'unit_price'=>$price,'shortfall_amount'=>$short,'uom'=>$line->uom,'created_at'=>now(),'updated_at'=>now()];$tot['ordered']+=$ordered;$tot['delivered']+=$delivered;$tot['missing']+=$open;$tot['value']+=$short;}$recovered++;$value+=$tot['value'];if($dry)continue;DB::transaction(function()use($local,$source,$lineRows,$tot){$id=DB::table('fulfillment_history_snapshots')->insertGetId(['sales_order_id'=>$local->id,'order_nbr'=>$local->acumatica_order_nbr,'customer_acumatica_id'=>$local->customer_acumatica_id,'order_date'=>$local->order_date?->toDateString(),'status'=>'Completed','observed_at'=>$source->completed_at??$source->synced_at??now(),'source'=>'historical_sql_dump','total_ordered_qty'=>$tot['ordered'],'total_delivered_qty'=>$tot['delivered'],'total_missing_qty'=>$tot['missing'],'historical_shortfall_amount'=>$tot['value'],'currency_id'=>$local->currency_id,'metadata'=>json_encode(['historical_source_id'=>$source->id]),'created_at'=>now(),'updated_at'=>now()]);foreach($lineRows as &$line)$line['snapshot_id']=$id;DB::table('fulfillment_history_lines')->insert($lineRows);});}$this->table(['Recovered','Missing','Rejected lines','Historical amount','Mode'],[[$recovered,$missing,$rejected,number_format($value,2),$dry?'DRY RUN':'IMPORTED']]);return self::SUCCESS;}
}
